import Foundation

actor UploadQueue {
    private var pending: [Upload] = []
    private var failed: [Upload.ID: Int] = [:]

    func enqueue(_ upload: Upload) {
        pending.append(upload)
    }

    func next() -> Upload? {
        guard !pending.isEmpty else { return nil }
        return pending.removeFirst()
    }

    func drain(using client: UploadClient) async {
        while let upload = next() {
            do {
                try await client.send(upload)
            } catch {
                let attempts = (failed[upload.id] ?? 0) + 1
                failed[upload.id] = attempts
                if attempts < 3 { pending.append(upload) }
            }
        }
    }
}

import Foundation

final class SessionRegistry: @unchecked Sendable {
    static let shared = SessionRegistry()

    private var sessions: [String: Session] = [:]
    private var lastAccess: [String: Date] = [:]

    func insert(_ session: Session) {
        sessions[session.token] = session
        lastAccess[session.token] = Date()
    }

    func session(for token: String) -> Session? {
        lastAccess[token] = Date()
        return sessions[token]
    }

    func evictExpired(olderThan interval: TimeInterval) {
        let cutoff = Date().addingTimeInterval(-interval)
        for (token, date) in lastAccess where date < cutoff {
            sessions[token] = nil
            lastAccess[token] = nil
        }
    }
}

