import Foundation

final class RateLimiter: @unchecked Sendable {
    private let lock = NSLock()
    private var tokens: Double
    private var lastRefill: Date
    private let capacity: Double
    private let refillPerSecond: Double

    init(capacity: Double, refillPerSecond: Double) {
        self.capacity = capacity
        self.refillPerSecond = refillPerSecond
        self.tokens = capacity
        self.lastRefill = Date()
    }

    func tryAcquire() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        let now = Date()
        tokens = min(capacity, tokens + now.timeIntervalSince(lastRefill) * refillPerSecond)
        lastRefill = now
        guard tokens >= 1 else { return false }
        tokens -= 1
        return true
    }
}

import Foundation

final class MetricsSink: @unchecked Sendable {
    private let queue = DispatchQueue(label: "com.trailhead.metrics")
    private var counters: [String: Int] = [:]
    private var timings: [String: [TimeInterval]] = [:]

    func increment(_ name: String, by value: Int = 1) {
        queue.async {
            self.counters[name, default: 0] += value
        }
    }

    func record(_ name: String, duration: TimeInterval) {
        queue.async {
            self.timings[name, default: []].append(duration)
        }
    }

    func snapshot() -> (counters: [String: Int], timings: [String: [TimeInterval]]) {
        queue.sync { (counters, timings) }
    }
}

