func connect() async {
    var backoff: Double = 1
    var connected = false
    repeat {
        do {
            try await socket.connect()
            connected = true
        } catch {
            logger.warning("socket connect failed: \(error.localizedDescription)")
            try? await Task.sleep(nanoseconds: UInt64(backoff * 1_000_000_000))
            backoff = min(backoff * 2, 30)
        }
    } while !connected
    status = .connected
}

