@MainActor
final class SettingsPersistence {
    private let settings: AppSettings
    private let defaults: UserDefaults

    init(settings: AppSettings, defaults: UserDefaults = .standard) {
        self.settings = settings
        self.defaults = defaults
        startSaving()
