import Foundation

struct TrailsAPI: Sendable {
    let baseURL: URL
    let session: URLSession

    func trails(near coordinate: Coordinate, radiusKm: Int) async throws -> [Trail] {
        var components = URLComponents(url: baseURL.appending(path: "trails"), resolvingAgainstBaseURL: false)!
        components.queryItems = [
            URLQueryItem(name: "lat", value: String(coordinate.latitude)),
            URLQueryItem(name: "lon", value: String(coordinate.longitude)),
            URLQueryItem(name: "radius", value: String(radiusKm)),
        ]
        let (data, response) = try await session.data(from: components.url!)
        guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode) else {
            throw APIError.badStatus
        }
        return try JSONDecoder.trailhead.decode([Trail].self, from: data)
    }
}

